    +Math.sin(dist*0.03-ang*5+t*0.8)*0.2+Math.sin(dist*0.07+ang*2-t*2)*0.15;
  const k1=0.7+Math.sin(t*0.3)*0.15,k2=0.3+Math.cos(t*0.4)*0.1;
  const reaction=Math.tanh((act-inh*k1+bg*k2+spiral+df*0.4)*2.2);
  const d2=Math.sqrt((sx-cx*1.5)**2+(sy-cy*0.8)**2),a2=Math.atan2(sy-cy*0.8,sx-cx*1.5);
  const r2=Math.tanh((Math.sin(d2*0.06-a2*2-t)+Math.sin(act*2+t))*1.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.1;
  const blend=reaction*0.55+r2*0.2+cell*0.15+micro*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,55,85],[18,110,115],[45,165,130],[140,195,95],[220,195,60],[225,140,55],[200,80,65],[160,50,75],[90,30,65],[40,18,58],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
